#include "FireThermalRuntime.hpp"
namespace elysium::world {void FireThermalRuntime::set(ThermalCell c){c.temperature=std::max(0.0,std::isfinite(c.temperature)?c.temperature:0.0);c.oxygen=std::clamp(std::isfinite(c.oxygen)?c.oxygen:0.0,0.0,1.0);c.flammability=std::clamp(std::isfinite(c.flammability)?c.flammability:0.0,0.0,1.0);cells_[c.id]=c;}void FireThermalRuntime::ignite(Cell id,double h){auto i=cells_.find(id);if(i==cells_.end())return;i->second.temperature=std::max(i->second.temperature,std::max(0.0,h));if(i->second.oxygen>0.05&&i->second.flammability>0.0&&!i->second.burning){i->second.burning=true;frontier_.push_back(id);}}std::vector<FireEvent>FireThermalRuntime::step(std::size_t budget){std::vector<FireEvent>o;for(std::size_t n=0;n<budget&&!frontier_.empty();++n){auto id=frontier_.front();frontier_.pop_front();auto&i=cells_[id];if(!i.burning)continue;double heat=i.flammability*i.oxygen*100.0;i.temperature+=heat;i.oxygen=std::max(0.0,i.oxygen-.02);if(i.oxygen>.05)frontier_.push_back(id);else i.burning=false;o.push_back({id,heat,heat*.1,heat*.05});}return o;}}
